    printf("IEEE1284_EXT_LINK = %u\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_ADDR = %u\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA = %u\n", IEEE1284_DATA);

    printf("\nParport EPP flags:\n");
    printf("PARPORT_EPP_FAST = %u\n", PARPORT_EPP_FAST);
    printf("PARPORT_W91284PIC = %u\n", PARPORT_W91284PIC);
    printf("PARPORT_EPP_FAST_16 = %u\n", PARPORT_EPP_FAST_16);
    printf("PARPORT_EPP_FAST_8 = %u\n", PARPORT_EPP_FAST_8);

    return 0;
}
